// Nova implementação otimizada para multiplicação de matrizes esparsas
SparseMatrix* SparseMatrix::multiplicacao(const SparseMatrix* A, const SparseMatrix* B) {
    if (!A || !B || A->getColunas() != B->getLinhas()) {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B!" << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), B->getColunas());

