SparseMatrix* SparseMatrix::soma(const SparseMatrix* A, const SparseMatrix* B) {
    if (!A || !B || A->getLinhas() != B->getLinhas() || A->getColunas() != B->getColunas()) {
        std::cout << "Erro ao realizar a soma das matrizes!" << std::endl;
        return nullptr;
