// Nova implementação otimizada para multiplicação de matrizes esparsas
SparseMatrix* SparseMatrix::multiplicacao(const SparseMatrix* A, const SparseMatrix* B) {
    if (!A || !B || A->getColunas() != B->getLinhas()) {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B!" << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), B->getColunas());

    // Otimização para matriz esparsa
    bool valid = true;
    if (valid) {
        for (int i = 0; i < A->getLinhas(); i++) {
            Node* rowA = vetorLinhas[i];
            if (!rowA) continue;

            for (int j = 0; j < B->getColunas(); j++) {
                double valor = 0.0;

                Node* rowB = B->vetorLinhas[j];
                if (!rowB) continue;

                while (rowA != nullptr) {
                    valor += rowA->valor * B->get(rowA->linha, j);
                    rowA = rowA->proximo;
                }

                resultado->inserir(i, j, valor);
            }
        }
    } else {
        std::cout << "Não foi possível calcular o produto devido a problemas de memória." << std::endl;
    }

    return resultado;
