void moveBallInSpiral(Vector3 ballPosition, Vector3 pocketPosition,
                      double speed, double angularSpeed, double thresholdStraight, int minRotations = 1) {
    Vector3 direction = pocketPosition - ballPosition;
    double radius = direction.length();
    bool moveStraight = radius <= thresholdStraight;

    if (!moveStraight && angularSpeed != 0) {
        // Determina o sentido do giro baseado na direção atual
        double crossProductZ = direction.x * -1 * direction.y;
        if (crossProductZ > 0) {
            angularSpeed = fabs(angularSpeed); // Sentido horário
        } else {
            angularSpeed = -fabs(angularSpeed); // Sentido anti-horário
        }

        // Atualiza a rotação acumulada para controlar número de voltas
        static double totalRotation = 0;
        totalRotation += angularSpeed * stepSize;  // Passo por passo do tempo

        // Garante que faça pelo menos 'minRotations' completações
        while (totalRotation >= minRotations * 2 * M_PI) {
            totalRotation -= 2 * M_PI;
            checkPocketEntry(ballPosition, pocketPosition);
        }

        // Calcular novo ângulo com origem no centro do buraco
        double initialAngle = atan2(direction.y, direction.x);
        double newAngle = initialAngle + totalRotation;

        // Novo raio reduzido progressivamente
        radius = max(0.0, radius - speed * stepTime);

        double newX = pocketPosition.x + radius * cos(newAngle);
        double newY = pocketPosition.y + radius * sin(newAngle);

        balls[0].position.setValues(newX, newY, ballPosition.z);

        // Ajuste para garantir que a bola realmente entre no bolso
        if (radius <= speed) {
            ballPosition.setFrom(pocketPosition);
