const Application = require("../../database/models/Application"); // Supondo que seja o model correto
const crypto = require("crypto");
const sendLogs = require("../../utils/sendLogs");
const moment = require("moment");
const chalk = require("chalk");
const { handleSharedApplication } = require("../../utils/expiredApplicationManager");
const config = {
